const $=q=>document.querySelector(q);
let dirty=1,curEra=-1,curRoom=-1,fi=null,pi=null,tab='launch',PL=null,resetArm=0,lastTrace=[];
const L={af:null,fuel:'Alcohol & LOX',pay:'Inert Ballast',st:0,load:100};
export const markDirty=()=>{dirty=1};
logSink.fn=(t,c)=>{const d=document.createElement('div');d.className=c;d.textContent=t;$('#lg').append(d);$('#lg').scrollTop=1e9;const pl=$('#padlog');if(pl&&PL){pl.append(d.cloneNode(true));while(pl.children.length>6)pl.firstChild.remove()}};
export function showTab(n){tab=n;applyTab()}
function applyTab(){document.querySelectorAll('[data-tab]').forEach(s=>s.hidden=s.dataset.tab!=tab);document.querySelectorAll('[data-tab-btn]').forEach(b=>b.classList.toggle('on',b.dataset.tabBtn==tab));const n=S.inc.filter(i=>i.st=='open'||i.st=='diag').length;$('#tb-design').textContent=n?`DESIGN BUREAU (${n})`:'DESIGN BUREAU'}
export const busy=()=>!!PL;
export function head(){document.querySelectorAll('[data-spd]').forEach(b=>b.classList.toggle('on',+b.dataset.spd==(S.speed??1)));$('#dt').textContent=dt();{const c=catchUp();$('#cu').textContent=c>1.05?` ×${c.toFixed(1)}, catching up with history`:''}$('#gt').textContent=S.gt;$('#ga').textContent=K(grant());$('#bg').textContent=K(S.b);$('#rp').textContent=Math.round(S.rep)+'%';$('#ra').textContent=Math.round(S.hi||0).toLocaleString()+' m';$('#rv').textContent=Math.round(S.hs||0).toLocaleString()+' m/s';$('#rd').textContent=((S.hd||0)/1000).toFixed(S.hd<1e5?1:0)+' km'}
function banner(sub,title,body){const b=$('#bn');b.className='';void b.offsetWidth;b.innerHTML=`<div class="d">${sub}</div><h1>${title}</h1><div>${body}</div>`;b.className='s'}
function setEra(){const e=era(),r=room(),root=document.documentElement;root.dataset.era=e;root.dataset.room=r;$('#era').textContent=`${S.nasa?'PROJECT MERCURY':ERAS[e][0]} • ${1946+Math.floor(S.day/360)}`;$('#site').textContent=ROOMS[r][0];document.querySelectorAll('[data-l]').forEach(n=>n.textContent=n.dataset.l.split('|')[e]);
if(e!=curEra){if(curEra>=0)banner(dt(),ERAS[e][0],ERAS[e][1]);curEra=e}if(r!=curRoom){if(curRoom>=0&&r>curRoom)banner('THE CONTROL ROOM GROWS',ROOMS[r][0],ROOMS[r][1]);curRoom=r}}

export function render(){dirty=0;head();setEra();const d=DIR[S.dir];$('#dr').innerHTML=d?`<div class="t">Directive ${S.dir+1}: ${d[0]}</div><div class="m">${d[1]>=120?'Reach 120 km at orbital speed (7,000 m/s) with a satellite.':`Reach ${d[1]} km (as measured by your tracking).`} Reward ${K(d[2])}.</div><div class="m nar">${NEWS[S.dir]}</div>`:'<div class="ok">All directives complete. First orbital flight achieved.</div>';
if(!S.nasa&&S.fs.f_orbit&&!nasaReady())$('#dr').innerHTML+=`<div class="c nasa"><div class="t">THE NATIONAL AERONAUTICS AND SPACE ACT</div><div class="m">Your satellite has Washington talking about a civilian space agency, but Congress moves at its own pace. The Act is expected around <b>${dateOf(ACT_DAY)}</b>; the calendar runs fast until then. Keep flying: science payloads still pay.</div></div>`;
if(nasaReady())$('#dr').innerHTML+=`<div class="c nasa"><div class="t">THE NATIONAL AERONAUTICS AND SPACE ACT</div><div class="m">${S.fs.f_orbit?'With a satellite in orbit,':'Whatever your progress,'} Washington wants a civilian space agency, with your programme at its core. Establishing it closes Phase One and sets up crewed flight.</div><button data-a="nasa">ESTABLISH NASA</button></div>`;else if(S.nasa)$('#dr').innerHTML+=`<div class="c nasa"><div class="ok">NASA established ${dateOf(S.nasa)}. Project Mercury (crewed flight) is the next chapter.</div><button data-a="summary">VIEW PHASE ONE SUMMARY</button></div>`;
if(S.nasa&&S.p2)$('#dr').innerHTML=p2Directive()+`<button data-a="summary">VIEW PHASE ONE SUMMARY</button>`;$('#tb-astro').hidden=!S.nasa;rAstro();rMissions();overlays();
rRoom();rRace();rLaunch();if(PL&&PL.phase!='flight')rPad();rDesign();rInc();rHangar();rFac();rStaff();rCrew();applyTab()}
const opt=(v,t,dis,cur)=>`<option value="${v}"${dis?' disabled':''}${cur==v?' selected':''}>${t}</option>`;
const payLock=(p,af)=>(PAY[p].sat&&satLock(af))||(PAY[p].req&&!done(PAY[p].req));
function rRoom(){const r=room(),c=crewList(),sl=slots();$('#crt').textContent=ROOMS[r][0].toUpperCase();$('#cr').innerHTML=roomSVG(r,c,sl,!!rt.F);$('#crm').textContent=`${ROOMS[r][1]} ${c.length} of ${sl} console${sl>1?'s':''} staffed.`;updateTrace(rt.F?rt.F.trace:lastTrace)}

function rLaunch(){if(rt.F)return;const rd=S.air.filter(a=>a.st=='r').reverse();if(!rd.find(a=>a.id==L.af))L.af=rd[0]&&rd[0].id;const af0=rd.find(a=>a.id==L.af),fls=af0?PROGS[af0.prog].fuels:Object.keys(FUEL);if(!fls.includes(L.fuel))L.fuel=fls[0];if(payLock(L.pay,af0))L.pay='Inert Ballast';if(L.st&&!stagingOK(af0))L.st=0;if(af0&&stagingOK(af0)&&!L.stSet)L.st=1;const af=af0,q=quoteLaunch(af,L.fuel,L.pay,L.st,L.load/100),pv=af?previewFlight(af,L.fuel,L.pay,L.st,L.load/100):null,py=PAY[L.pay];
let sci='';if(pv&&py.sci){const val=py.sci*(py.sat?1:Math.max(.2,Math.min(2.5,pv.alt/30000)))*pv.sv;sci=py.sat?`<div class="r"><span class="d">Science on orbit</span><b>~${K(val*.5)}</b></div>`:`<div class="r"><span class="d">Recovery odds</span><b class="${pv.rec.none||pv.rec.p<.3?'bad':pv.rec.p<.6?'wn':'ok'}">${pv.rec.none?'no recovery system':'~'+Math.round(pv.rec.p*100)+'%'+(pv.rec.burn>0?' (re-entry too fast for its heat protection)':'')}</b></div><div class="r"><span class="d">Science if recovered / telemetry only</span><b>~${K(val*.5)} / ~${K(val*.5*(py.tlm||0)*(.4+.2*tiers().v))}</b></div>`}
$('#lc').innerHTML=`<select data-s="af">${rd.length?rd.map(a=>opt(a.id,`${a.label} (built ${a.built})`,0,L.af)).join(''):'<option>No airframe in the hangar</option>'}</select>
<select data-s="st">${opt(0,'Upper stage alone',0,L.st)}${opt(1,stagingOK(af)?`Full stack: booster stage + upper stage (+${K(8000)})`:'No booster stage on this rocket',!stagingOK(af),L.st)}</select>
<select data-s="fuel">${Object.keys(FUEL).map(f=>opt(f,`${f} (${af?K(fuelCost(af,f,L.load/100)):'$'+FUEL[f].kg+'/kg'}, Isp ${FUEL[f].isp}s)${!fls.includes(f)?' [not this rocket]':''}`,!fls.includes(f),L.fuel)).join('')}</select>
<select data-s="pay">${Object.keys(PAY).filter(p=>!PAY[p].msn).map(p=>opt(p,`${p} (${K(PAY[p].c)}, ${PAY[p].m} kg${PAY[p].sci?`, science ~${K(PAY[p].sci)}`:''})${PAY[p].req&&!done(PAY[p].req)?` [needs ${BY[PAY[p].req].n}]`:PAY[p].sat&&satLock(af)?' [needs a satellite launcher]':''}`,payLock(p,af),L.pay)).join('')}</select>
<div class="r" style="margin-top:8px"><span class="d">Propellant load (${af?Math.round(withProg(af.prog,()=>spec(af.pk).f)*FUEL[L.fuel].den*L.load/100):0} kg)</span><b id="ldv">${L.load}%</b></div><input type="range" data-s="load" min="10" max="100" step="5" value="${L.load}" style="width:100%">
${pv?`<div class="c"><div class="t">PRE-FLIGHT ESTIMATE (calculated, ±${Math.round(pv.sg*100)}%)</div><div class="r"><span class="d">Liftoff thrust-to-weight</span><b class="${pv.twr<1.05||pv.twr>pv.lim*.85?'bad':pv.twr<1.5?'wn':'ok'}">${pv.twr.toFixed(2)}</b></div><div class="r"><span class="d">Burnout load / structural limit</span><b class="${pv.gEnd>pv.lim*.85?'bad':'ok'}">${pv.gEnd.toFixed(1)} g / ${pv.lim.toFixed(1)} g</b></div><div class="r"><span class="d">Peak altitude</span><b>${fa(Math.round(pv.alt/100)*100,{s:1,r:100})}</b></div><div class="r"><span class="d">Max speed</span><b>~${Math.round(pv.spd/10)*10} m/s</b></div>${L.st&&stagingOK(af)?`<div class="r"><span class="d">Horizontal speed above 120 km</span><b class="${pv.orbit?'ok':pv.hv>6500?'wn':'bad'}">${pv.orbit?'orbit':`~${Math.round(pv.hv/10)*10} m/s of 7,000`}</b></div><div class="m">Orbit needs about 7,000 m/s of horizontal speed above 120 km. Better guidance (instrumentation) flies a flatter path and wastes less climbing.</div>`:''}<div class="r"><span class="d">Peak aerodynamic load (calm air)</span><b class="${pv.maxQ>.85?'bad':pv.maxQ>.6?'wn':'ok'}">${Math.round(pv.maxQ*100)}% of limit</b></div><div class="r"><span class="d">Peak skin heating</span><b class="${pv.maxH>1?'bad':pv.maxH>.8?'wn':'ok'}">${Math.round(pv.maxH*100)}% of limit</b></div><div class="r"><span class="d">Downrange</span><b>~${(pv.rng/1000).toFixed(pv.rng<1e5?1:0)} km</b></div>${sci}<div class="m">Burn about ${pv.burn}s. More propellant adds speed but weight and cost; a heavy payload cuts everything and can stop liftoff. Faster flights are harder to recover.</div></div>`:''}
<div class="m">Fuel record: ${S.fr[L.fuel]||0} successful flights.${af&&af.pk.some(i=>!conf(i))?` Unproven systems aboard: ${af.pk.filter(i=>!conf(i)).length} (raises the chance of a hidden fault).`:''} Range fee ${K(pad())} included.${rangeData(1e4)?' Successful flights earn a Defense Department range data contract.':''}</div><button data-a="count"${q.err?' disabled':''}>BEGIN COUNTDOWN${q.t?' ('+K(q.t)+')':''}</button>${S.staff.director?`<button data-a="autoSet">SET AS DIRECTOR'S STANDING ORDERS</button>`:''}<div class="m bad">${q.err||''}</div>`}

// THE LAUNCH VIEW: the control room fills the screen from rollout to splashdown.
// The count starts at T-30. Propellant loading runs inside it; the stations are polled from T-15; anything not ready, or any NO-GO, holds the clock.
const COUNT_FROM=30,POLL_AT=15,COUNT_RATE=2; // count-seconds per real second
function padOpen(){$('#pad').hidden=false;$('#padlog').innerHTML='';$('#comms').hidden=true;document.body.classList.add('padopen')}
function padClose(){clearInterval(pi);pi=null;PL=null;$('#pad').hidden=true;$('#fl').hidden=true;$('#comms').hidden=true;document.body.classList.remove('padopen');dirty=1;render()}
function bubbles(){const b={};if(!PL)return b;if(PL.shown){for(const l of PL.P.lines.slice(0,PL.shown))b[l.id]={t:l.go?'GO':'NO-GO',c:l.go?'go':'no'}}
else if(PL.phase=='count'){const who=S.crew.bstr?'bstr':'tc';if(PL.filling)b[who]={t:'FUELING',c:'wn'};else if(PL.fuel>=PL.target-.005&&PL.fuel>0)b[who]={t:'TANKS LOADED',c:'go'}}return b}
const clockTxt=()=>{const c=Math.max(0,Math.ceil(PL.clock));return`T-00:${String(c).padStart(2,'0')}`};
function holdWhy(){if(!PL)return'';if(PL.hold)return PL.hold;return''}
// Light update every tick: clock and tank only. rPad() redraws the room when something changes.
function padTickUI(){if(!PL)return;const ph=$('#padph');if(PL.phase=='count')ph.textContent=`${clockTxt()} ${PL.hold?'HOLDING':PL.run?'COUNTING':''}`;const f=$('#tankfill'),pc=$('#tankpct');if(f)f.style.width=PL.fuel*100+'%';if(pc)pc.textContent=Math.round(PL.fuel*100)+'%'}
function rPad(){if(!PL)return;const r=room(),af=S.air.find(a=>a.id==PL.P.af)||{label:PL.label},P=PL.P,pollDone=PL.shown>=P.lines.length;
$('#padt').textContent=`${ROOMS[r][0]} — ${PL.label}`;$('#padroom').innerHTML=roomSVG(r,crewList(),slots(),PL.phase=='flight',bubbles());updateTrace(rt.F?rt.F.trace:rt.M?rt.M.trace:lastTrace);
if(PL.phase=='done'&&PL.msn){const R=PL.res;$('#padph').textContent=R.lost?'CREW LOST':R.ok?'MISSION COMPLETE':'MISSION FAILED';$('#paddlg').innerHTML=`<div class="t ${R.ok?'ok':'bad'}">${R.ok?'Splashdown and recovery.':R.lost?'The crew has been lost.':'The mission did not go to plan.'}${R.met?' Directive fulfilled.':''}</div><div class="m">${R.text}</div><button data-a="closepad" class="big">RETURN TO OPERATIONS</button>`;return}
if(PL.phase=='done'){const R=PL.res;$('#padph').textContent=R.ok?(R.why=='orbit'?'ORBIT':'FLIGHT COMPLETE'):R.why=='abort'?'ABORTED':'VEHICLE LOST';$('#paddlg').innerHTML=`<div class="t ${R.ok?'ok':'bad'}">${R.ok?(R.why=='orbit'?'Orbital insertion confirmed.':'Impact recorded downrange.'):R.why=='abort'?'Range safety terminated the flight.':'Track lost. The vehicle has failed.'}</div><div class="m">See the log for records, science and any incident report.</div><button data-a="closepad" class="big">RETURN TO OPERATIONS</button>`;return}
if(PL.phase=='flight'){$('#paddlg').innerHTML=PL.msn&&rt.M&&rt.M.pend?decisionHTML(rt.M):'';return}
padTickUI();
let h=`<div class="tank"><div class="r"><span class="d">Propellant ${PL.filling?'loading':'on board'}</span><b><span id="tankpct">${Math.round(PL.fuel*100)}%</span> <span class="d">of ${Math.round(PL.target*100)}% planned</span></b></div><div class="bar"><i id="tankfill" style="width:${PL.fuel*100}%"></i><s style="left:${PL.target*100}%"></s></div></div>`;
if(!PL.filling&&PL.fuel<.01)h+=S.crew.bstr?'':`<div class="m">No Structures & Booster Engineer on the net: loading is yours, and the count will hold at T-${POLL_AT} until the tanks are full.</div><button data-a="fuel">COMMENCE FUELING & PRESSURIZATION</button>`;
else if(!PL.filling&&PL.fuel<PL.target-.005&&!S.crew.bstr)h+=`<button data-a="topoff">TOP OFF LOX (boil-off has cost ${Math.round((PL.target-PL.fuel)*100)}%)</button>`;
h+=P.lines.slice(0,PL.shown).filter(l=>l.msg&&(!l.go||l.id=='tc'||/Fixed|Held/.test(l.msg))).map(l=>`<div class="m"><b>${STN[l.id].s}:</b> ${l.msg}</div>`).join('');
if(PL.shown&&!pollDone)h+=`<div class="m wn">${r>=4&&S.crew.fd?'FLIGHT: "All stations, go/no-go for launch."':'Polling the stations…'}</div>`;
if(pollDone&&P.lines.length==1)h+='<div class="m">Nobody else is on the net. Launch crew hired in Personnel will catch faults before they fly.</div>';
if(pollDone&&P.wk&&P.wind&&af.pk){const pw=previewFlight(af,L.fuel,L.pay,L.st,PL.fuel,P.wind);h+=`<div class="r"><span class="d">Aero load in these winds</span><b class="${pw.maxQ>.85?'bad':pw.maxQ>.6?'wn':'ok'}">${Math.round(pw.maxQ*100)}% of limit</b></div>`}
if(PL.hold)h+=`<div class="t bad">HOLD: ${PL.hold}</div>`;
const nl=P.lines.find(x=>!x.go);h+='<div class="padbtns">';
if(pollDone&&P.nogo)h+=`${nl.wind?`<button data-a="fixpad"${S.b<fixCost()?' disabled':''}>HOLD FOR WEATHER (${K(fixCost())}, 2 days)</button>`:`<button data-a="fixpad"${S.b<fixCost()?' disabled':''}>TROUBLESHOOT (${K(fixCost())}, ~${Math.round(fixOdds(P)*100)}% to fix)</button>`}<button data-a="scrub">SCRUB (${K(scrubCost())})</button><button data-a="over" class="danger">OVERRIDE AND CONTINUE</button>`;
else if(PL.hold&&PL.userHold)h+=`<button data-a="resume" class="big">RESUME COUNT</button><button data-a="stand">STAND DOWN</button>`;
else if(PL.hold)h+=`<button data-a="stand">STAND DOWN</button>`;
else h+=`<button data-a="hold">HOLD THE COUNT</button><button data-a="stand">STAND DOWN</button>`;
$('#paddlg').innerHTML=h+'</div>'}
function startCount(){const af=S.air.find(a=>a.id==L.af&&a.st=='r');if(!af||quoteLaunch(af,L.fuel,L.pay,L.st,L.load/100).err)return;
PL={P:poll(af,L.fuel,L.st&&stagingOK(af)?1:0),shown:0,phase:'count',fuel:0,target:L.load/100,filling:false,label:af.label,clock:COUNT_FROM,run:true,hold:'',userHold:false,over:false};padOpen();if(S.crew.bstr)startFuel();
clearInterval(pi);pi=setInterval(countTick,100);rPad()}
// One 100 ms tick of the count.
function countTick(){if(!PL||PL.phase!='count')return;let redraw=false;const P=PL.P;
if(PL.filling){PL.fuel=Math.min(PL.target,PL.fuel+(S.crew.bstr?.02:.01)*PL.target);if(PL.fuel>=PL.target){PL.filling=false;if(!S.crew.bstr)PL.fuel=Math.max(.05,Math.min(1,PL.target*(1+.04*gauss())));lg(S.crew.bstr?'[BSTR] Tanks loaded and pressurized to plan.':`[PAD] Tanks loaded: about ${Math.round(PL.fuel*100)}% against ${Math.round(PL.target*100)}% planned. Pressurization nominal.`,'ok');if(PL.hold=='Propellant loading incomplete.')PL.hold='';redraw=true}}
if(PL.run&&!PL.hold){PL.clock-=COUNT_RATE*.1;
if(PL.clock<=POLL_AT&&!PL.shown&&!PL.polling){if(PL.filling||PL.fuel<.01){PL.hold='Propellant loading incomplete.';PL.clock=POLL_AT;redraw=true}else{PL.polling=1;PL.pollT=0;PL.shown=1;redraw=true}}
if(PL.polling&&PL.shown<P.lines.length&&++PL.pollT>=(room()>=4?4:6)){PL.pollT=0;PL.shown++;redraw=true}
if(PL.polling&&PL.shown>=P.lines.length){PL.polling=0;if(P.nogo&&!PL.over){PL.hold='NO-GO called.';redraw=true}}
if(PL.clock<=2&&PL.shown<P.lines.length){PL.hold='Awaiting station reports.';PL.clock=2;redraw=true}
if(PL.clock<=0){PL.clock=0;return launchFlight(PL.over)}}
if(redraw)rPad();else padTickUI()}
function startFuel(){if(!PL||PL.filling)return;PL.filling=true;rPad()}
// Every day held on the pad boils off LOX. BSTR tops it off as it goes.
function holdDay(){if(!PL)return;if(S.crew.bstr)lg('[BSTR] LOX topped off during the hold.','ok');else{PL.fuel=Math.max(.05,PL.fuel*.95);lg(`[PAD] LOX boil-off during the hold. Propellant now about ${Math.round(PL.fuel*100)}%.`,'wn')}}
function areaCard(a){const c=cnt(a),open=itemsOf(a).filter(p=>!done(p.id)),avail=open.filter(proposed),later=open.length-avail.length;
let h=`<div class="c"><div class="t">${vehA(a)?PROGS[S.cur].n.toUpperCase()+': ':''}${AREAS[a].toUpperCase()}${vehA(a)?'':' <span class="d">(all rockets)</span>'}</div>${knowBlock(a)}<div class="t" style="margin-top:8px;font-size:.8em">RESEARCH</div><div class="m">Complete ${c.d}/${c.n} | confirmed ${c.c}${vehA(a)?(PROGS[S.cur].ms&&t1opts(a).length?` (${bthP(a)[0]} for a breakthrough)`:''):` (${bth(a)[0]} for a breakthrough, ${bth(a)[1]} for the second milestone)`}</div>`;
itemsOf(a).filter(p=>done(p.id)).forEach(p=>{h+=`<div class="m">✓ ${p.n}: ${desc(p)}</div>`;const qa=a=='c'||a=='e';if(((a=='p'&&S.fac.stand)||qa)&&!conf(p.id)){const j=job(x=>x.k=='gt'&&x.id==p.id),r=groundTestLock(p.id);h+=j?`<div class="m wn">${qa?'Qualification tests':'Static firing'}: <span data-j="gt${p.id}">${j.t}s</span></div>`:`<button data-a="gt" data-id="${p.id}"${r?' disabled':''}>${qa?'QUALIFICATION TEST ($4,000, 110s)':'GROUND TEST ($2,000, 30s)'}</button>`}});
avail.forEach(p=>h+=cm(p,1));if(later)h+=`<div class="m">${later} more idea${later>1?'s':''} will be proposed as your engineers prove what they have.</div>`;
if(vehA(a)&&(!PROGS[S.cur].ms||!t1opts(a).length))return h+'</div>';const t1=t1opts(a),t2=vehA(a)?null:MSL.find(m=>m.a==a&&m.tier==2),chosen=t1.find(m=>done(m.id)||job(j=>j.k=='pk'&&j.id==m.id));
h+=`<div class="msb">`+(chosen?`<div class="t">FIRST MILESTONE</div>${msRow(chosen)}${t2?`<div class="t" style="margin-top:8px">SECOND MILESTONE</div>${msRow(t2)}`:''}`:S.bt[a]?`<div class="t">BREAKTHROUGH: CHOOSE ONE APPROACH</div>${S.ear&&S.ear[a]?`<div class="m ok">Congress has earmarked ${K(S.ear[a])} toward this programme.</div>`:''}${t1.map(msRow).join('<div class="or">or</div>')}`:`<div class="m">A breakthrough after ${bthP(a)[0]} confirmed packages (${c.c}/${bthP(a)[0]}) will open a choice of approaches.</div>`)+'</div></div>';return h}
