export function refreshTimers(){head();document.querySelectorAll('[data-j]').forEach(n=>{const j=job(x=>x.k+x.id==n.dataset.j);if(j)n.textContent=j.t+'s'});document.querySelectorAll('[data-q]').forEach(n=>{const q=S.aq[+n.dataset.q];if(!q)return;const p=Math.round((q.tot-q.t)/q.tot*100);n.textContent=`${p}% (${Math.ceil(q.t/buildRate(q))}s)`;const bar=document.querySelector(`[data-qb="${n.dataset.q}"]`);if(bar)bar.style.width=p+'%'})}
export const needsRender=()=>dirty;
function rStaff(){const h=$('#sf');if(!h)return;const a=S.auto,card=(t,d,btn)=>`<div class="c"><div class="t">${t}</div><div class="m">${d}</div>${btn}</div>`;
h.innerHTML=`<div class="r"><span class="d">Payroll per 30s funding cycle</span><b>${K(payroll())}</b></div>`+
card(`BUILD TEAMS (${bteams()}/${BTEAM_MAX})`,'Factory crews. Each one works a different item in the build queue at the same time: airframes, upgrades, capsules. $800 per cycle for each team beyond the first.',bteams()<BTEAM_MAX?`<button data-a="hire" data-id="bteam"${S.b<bteamCost()?' disabled':''}>HIRE BUILD TEAM (${K(bteamCost())})</button>`:'<div class="ok">Fully staffed.</div>')+
card(`ENGINEERING TEAMS (${S.teams}/6)`,'Each team works one job at a time: packages, investigations, fixes, retrofits, ground tests. $1,200 per cycle for each team beyond the first two.',S.teams<6?`<button data-a="hire" data-id="team"${S.b<teamCost()?' disabled':''}>HIRE ENGINEERING TEAM (${K(teamCost())})</button>`:'<div class="ok">Fully staffed.</div>')+
card('PUBLIC RELATIONS SPECIALIST','Halves the reputation lost to failures and slowly rebuilds it. $1,000 per cycle.',S.staff.pr?'<div class="ok">On staff.</div>':`<button data-a="hire" data-id="pr"${S.b<HIRE.pr[0]?' disabled':''}>HIRE PR SPECIALIST (${K(HIRE.pr[0])})</button>`)+
card('LAUNCH DIRECTOR',S.staff.director?`Flies ready airframes unattended every ~15s when funds allow, runs the poll and scrubs on any NO-GO. Orders: ${a.fuel}, ${a.pay}, ${a.st?'booster':'single stage'}, ${Math.round(a.load*100)}% propellant. Set them from the Launch tab. $2,500 per cycle.`:'Runs countdowns for you from standing orders. $2,500 per cycle.',S.staff.director?`<button data-a="autoOn">AUTOMATION: ${a.on?'ON (click to stop)':'OFF (click to start)'}</button>`:`<button data-a="hire" data-id="director"${S.b<HIRE.director[0]?' disabled':''}>HIRE LAUNCH DIRECTOR (${K(HIRE.director[0])})</button>`)}
function rCrew(){const h=$('#crew');if(!h)return;const sl=slots(),n=crewList().length;let o=`<div class="r"><span class="d">Consoles staffed</span><b>${n} / ${sl}</b></div><div class="m">${ROOMS[room()][0]}. Control-room upgrades in Hangar & Base add consoles. Staffed stations can catch hidden faults during the countdown poll.</div>`;
for(const id in STN){const s=STN[id],lk=stnLock(id);o+=`<div class="c"><div class="r"><b>${s.s} — ${s.n}</b><span class="${S.crew[id]||id=='tc'?'ok':'d'}">${id=='tc'||S.crew[id]?'On console':s.req&&!S.fac[s.req]?'Locked':'Vacant'}</span></div><div class="m">${s.d}${s.sal?` ${K(s.sal)} per cycle.`:''}</div>`+(id=='tc'?'':S.crew[id]?`<button data-a="dismiss" data-id="${id}">RELEASE FROM CONSOLE</button>`:`<button data-a="crew" data-id="${id}"${lk?' disabled':''}>HIRE (${K(s.c)})</button>${lk?`<div class="m">${lk}</div>`:''}`)+'</div>'}
h.innerHTML=o}
document.addEventListener('input',e=>{if(e.target.dataset.s=='load')$('#ldv').textContent=e.target.value+'%'});
document.addEventListener('change',e=>{const ds=e.target.dataset;if(ds.focus){setFocus(+ds.focus,e.target.value);save();return render()}if(ds.mv){S.p2.lv=+e.target.value;return render()}if(ds.mb){S.p2.lb=+e.target.value;return render()}if(ds.mf){S.p2.lf=e.target.value;return render()}if(ds.mc){const v=e.target.value;S.p2.lc=isNaN(+v)?v:+v;return render()}if(e.target.dataset.ap){S.ap.n=+e.target.value;save();return render()}const k=e.target.dataset.s;if(!k)return;L[k]=k=='st'||k=='load'?+e.target.value:e.target.value;if(k=='st')L.stSet=1;if(k=='af')L.stSet=0;render()});
document.addEventListener('click',e=>{const t=e.target.closest('[data-tab-btn]');if(t)return showTab(t.dataset.tabBtn);const sp=e.target.closest('[data-spd]');if(sp){S.speed=+sp.dataset.spd;return head()}const b=e.target.closest('button[data-a]');if(!b||b.disabled)return;const a=b.dataset.a,id=b.dataset.id;
if(a=='count')startCount();else if(a=='fuel')startFuel();else if(a=='topoff'){if(PL){PL.fuel=PL.target;lg('[PAD] LOX topped off.','ok')}}else if(a=='hold'){if(PL){PL.hold='Held by the Test Conductor.';PL.userHold=true}}else if(a=='resume'){if(PL){PL.hold='';PL.userHold=false}}else if(a=='over'){if(PL){PL.over=true;PL.hold='';lg('[TC] Continuing the count over a NO-GO.','bad')}}else if(a=='scrub'){if(PL)scrub(PL.P);padClose()}else if(a=='stand'){if(PL&&PL.fuel>.01)scrub(PL.P);padClose()}else if(a=='closepad')padClose();
else if(a=='abort'&&rt.F)finish(0,'abort');else if(a=='abort'&&rt.M)manualAbort(rt.M);else if(a=='com')commission(id);else if(a=='ord')orderAirframes(+b.dataset.n);else if(a=='retro')startRetrofit(id);else if(a=='hire')hire(id);else if(a=='autoOn')toggleAuto();else if(a=='autoSet')setOrders(L);else if(a=='fac')buildFacility(id);else if(a=='inv')startInvestigation(+id);else if(a=='fix')chooseFix(+id,b.dataset.f);
else if(a=='fixpad'){if(PL){troubleshoot(PL.P);holdDay();if(!PL.P.nogo){PL.hold='Fixed. Resume when ready.';PL.userHold=true}}}else if(a=='publish')publishBlueprint();else if(a=='upgrade')queueRetrofit(+id);else if(a=='cancelq')cancelQueue(+id);
else if(a=='nasa'){formNASA();ensureP2();save();render();return showSummary()}else if(a=='summary')return showSummary();else if(a=='closesum'){$('#sum').hidden=true;return}else if(a=='runlog')return showRunLog();else if(a=='copylog')return copyLog();
else if(a=='aptog')S.ap.on=S.ap.on?0:1;
else if(a=='mcount')startMissionCount();else if(a=='mord')orderVehicle(id);else if(a=='mdec'){if(rt.M){mChoose(rt.M,+id);rPad()}return}
else if(a=='txview')return showTranscript();else if(a=='prog'){if(S.progs[id])S.cur=id}else if(a=='pstart')startProgramme(id);else if(a=='rev')startReview(id);else if(a=='reg')chooseRegime(id);else if(a=='offy')officeChoice(true);else if(a=='offn')officeChoice(false);else if(a=='chimps')startChimps();
else if(a=='selt'){selSet.has(+id)?selSet.delete(+id):selSet.add(+id)}else if(a=='selok'){if(selectCrew([...selSet]))selSet.clear()}else if(a=='asg')asgAstro(+id,'mr');
else if(a=='memok'){S.p2.memo=null;$('#sum').hidden=true}else if(a=='sec1'){$('#sum').innerHTML=sectionHTML();$('#sum').hidden=false;return}
else if(a=='crew')hireStation(id);else if(a=='dismiss')dismissStation(id);else if(a=='gt')groundTest(id);
else if(a=='reset'){if(!resetArm){resetArm=1;b.textContent='CLICK AGAIN TO WIPE THE SAVE';setTimeout(()=>{resetArm=0;const r=$('#rs');if(r)r.textContent='RESET'},4000);return}resetArm=0;b.textContent='RESET';if(fi)clearInterval(fi);if(pi)clearInterval(pi);fi=pi=null;rt.F=null;PL=null;$('#pad').hidden=true;resetState();ensureStarter();$('#lg').innerHTML='';$('#fl').hidden=true;$('#lc').hidden=false;curEra=curRoom=-1;document.documentElement.classList.remove('flying')}
save();dirty=1;render()});
export function initUI(){load();ensureStarter();$('#fl').hidden=true;$('#lc').hidden=false;logSink.fn('[SYSTEM] Radar tracking and a radio beacon are online. Expect approximate data only.','');logSink.fn('[SYSTEM] Appropriations arrive every 30 seconds.','');render()}

// End-of-phase summary: your timeline and how your firsts compare with the Soviets and the real US programme.
function showSummary(){const sv=k=>{const f=FIRSTS.find(x=>x[0]==k);return f&&f[5]&&S.rvd[f[5]]?dateOf(S.rv[f[5]]):'—'};
$('#sum').innerHTML=`<div class="sumbox"><h1>PHASE ONE COMPLETE</h1><div class="d">From sounding rockets to ${S.fs.f_orbit?'orbit':'the edge of space'} • ${dt()}</div>
<div class="sumg"><div><h2>YOUR PROGRAMME</h2>${S.hist.map(h=>`<div class="first"><span>${h.t}</span><b class="d">${dateOf(h.d)}</b></div>`).join('')||'<div class="m">No milestones recorded.</div>'}</div>
<div><h2>FIRSTS: YOU, THE SOVIETS, HISTORY</h2><div class="tw"><table><tr><th>First</th><th>You</th><th>Soviets</th><th>Real US</th></tr>${FIRSTS.map(f=>`<tr><td>${f[1].replace(/^First /,'')}</td><td class="${S.fs[f[0]]=='us'?'ok':S.fs[f[0]]=='second'?'wn':'d'}">${S.fsd[f[0]]!=null?dateOf(S.fsd[f[0]]):'—'}</td><td>${sv(f[0])}</td><td class="d">${HISTUS[f[0]]||''}</td></tr>`).join('')}</table></div>
<div class="m">Records: ${Math.round(S.hi).toLocaleString()} m altitude, ${Math.round(S.hs).toLocaleString()} m/s, ${Math.round((S.hd||0)/1000)} km downrange. ${S.ok} successful flights.</div></div></div>
<button data-a="closesum">CONTINUE PLAYING</button></div>`;$('#sum').hidden=false}

// RUN LOG viewer: key moments by play time, plus the whole log as JSON to copy.
const mmss=s=>`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;
const KEY=/DIRECTIVE FULFILLED|HISTORIC FIRST|America answers|BREAKTHROUGH|Milestone|CONTRACT|\[BASE\]|LAUNCH CREW\] .* takes|PERSONNEL\]|\[WIRE\]|Published blueprint|WASHINGTON|RECORD\] New altitude|DEAD END/;
function showRunLog(){const D=S.dev||{ps:0,ev:[],snap:[],fl:0},key=D.ev.filter(e=>e.m&&KEY.test(e.m));
$('#sum').innerHTML=`<div class="sumbox"><h1>RUN LOG</h1><div class="d">Play time ${mmss(D.ps)} • ${dt()} • ${D.fl} flights • ${D.ev.length} events, ${D.snap.length} snapshots</div>
<div class="tw" style="margin:14px 0"><table><tr><th>Play time</th><th>Date</th><th>Event</th></tr>${key.map(e=>`<tr><td>${mmss(e.t)}</td><td class="d">${dateOf(e.d)}</td><td>${e.m.replace(/</g,'&lt;')}</td></tr>`).join('')||'<tr><td colspan="3" class="d">Nothing recorded yet.</td></tr>'}</table></div>
<div class="two"><button data-a="copylog">COPY FULL RUN LOG (JSON)</button><button data-a="closesum">CLOSE</button></div><div class="m" id="copymsg">Paste the copied log into the chat to have the run analysed.</div><textarea id="logjson" readonly hidden style="width:100%;height:160px;margin-top:6px;font:11px monospace;background:var(--bg);color:var(--ink);border:1px solid var(--ln)"></textarea></div>`;$('#sum').hidden=false}
function copyLog(){const txt=JSON.stringify({game:'Project Vanguard',saved:new Date().toISOString(),...S.dev});const ta=$('#logjson');ta.value=txt;
const fallback=()=>{ta.hidden=false;ta.focus();ta.select();$('#copymsg').textContent='Copying was blocked here. The log is selected below: press Ctrl+C.'};
try{navigator.clipboard.writeText(txt).then(()=>{$('#copymsg').textContent=`Copied ${Math.round(txt.length/1024)} KB to the clipboard.`},fallback)}catch(e){fallback()}}

// MERCURY FLIGHTS in the launch view: the same count and poll, then a mission timeline with crew decisions instead of the rocket physics.
function startMissionCount(){const P=S.p2,v=P&&P.veh.find(x=>x.id==P.lv),af=P&&S.air.find(a=>a.id==P.lb&&a.st=='r');if(!v||!af)return;const crew=P.lc||'none',fuel=P.lf||'Alcohol & LOX',plan=boosterPlan(af,fuel,v.mt);if(!plan.ok||crewLock(crew,af))return;
PL={P:poll(af,fuel,plan.st),shown:0,phase:'count',fuel:0,target:1,filling:false,label:`${MT[v.mt].full}: capsule #${v.id} on ${af.label}`,clock:30,run:true,hold:'',userHold:false,over:false,msn:{vid:v.id,crew,af:af.id,fuel}};padOpen();if(S.crew.bstr)startFuel();clearInterval(pi);pi=setInterval(countTick,100);rPad()}
function launchMission(over){const P=PL.P,m=beginMission(PL.msn.vid,PL.msn.crew,{af:PL.msn.af,fuel:PL.msn.fuel,latent:P.fault,over,wind:P.wind});if(!m)return;rt.M=m;m.shownTx=0;$('#ctx').innerHTML='';$('#comms').hidden=false;commsDraw(m);clearInterval(pi);pi=null;PL.phase='flight';lg('[TC] Ignition. Liftoff!','hd');document.documentElement.classList.add('flying');$('#fl').hidden=false;rPad();missionDraw(m);
$('#ln').textContent=m.crew&&!m.crew.chimp?`${m.crew.name} is aboard. Decisions in flight are theirs, with CAPCOM's help.`:'Telemetry from the capsule.';fi=setInterval(missionTick,250)}
function missionTick(){const m=rt.M;if(!m)return;if(m.pend){$('#padph').textContent='DECISION';return}const r=stepMission(m,m.crew&&!m.crew.chimp?5:10);commsDraw(m);const p=reading(m);m.trace.push(Math.round(p.alt*1000));
$('#padph').textContent=r=='decide'?'DECISION':`T+${Math.floor(m.t/60)}:${String(Math.floor(m.t%60)).padStart(2,'0')} ${m.t<(m.m.sep||40)?'POWERED FLIGHT':m.t<(m.m.ent||m.m.chute)?'COAST':m.t<m.m.chute?'RE-ENTRY':'DESCENT AND RECOVERY'}`;
missionDraw(m);if(r=='decide')rPad();if(r=='end')finishMission()}
function missionDraw(m){const p=reading(m),r=room(),ch=[{lab:'ALTITUDE',v:p.alt*1000,max:Math.max(5000,...m.trace,1)*1.05,txt:`${p.alt.toFixed(1)} km`},{lab:'VELOCITY',v:p.v,max:m.mt=='bj'?6000:m.mt=='lj'?800:2600,txt:`${Math.round(p.v)} m/s`},{lab:'G-LOAD',v:p.g,max:16,txt:`${p.g.toFixed(1)} g`},{lab:'CABIN TEMP',v:p.temp,max:60,txt:`${p.temp} °C`}];
$('#gpanel').innerHTML=gaugesSVG(Math.max(r,2),ch,true);updateTrace(m.trace)}
function decisionHTML(m){const k=m.pend.k,os=mOptions(m,k);return`<div class="t bad">${m.pend.q}</div><div class="m">${m.pend.ctl?'Your call as Test Conductor.':`${m.crew.name} has to choose. CAPCOM ${S.crew.capcom?'is on the loop':'is not staffed'}.`}</div><div class="padbtns">${os.map(o=>`<button data-a="mdec" data-id="${o.i}"${o.ok?'':' disabled'}>${o.t.toUpperCase()}${o.ok?` (~${Math.round(mOdds(m,k,o)*100)}%)`:o.need=='man'?' (needs manual control fitted)':' (needs CAPCOM)'}</button>`).join('')}</div>`}
function finishMission(){clearInterval(fi);fi=null;const m=rt.M;const res=endMission(m);lastTrace=m.trace.slice();rt.M=null;document.documentElement.classList.remove('flying');
if(PL){PL.phase='done';PL.res={ok:res.ok,met:res.met,lost:res.lost,text:m.log.slice(-4).join(' ')}}$('#fl').hidden=true;dirty=1;render();rPad()}
// AIR-TO-GROUND TRANSCRIPT: new lines are appended as the mission clock reaches them, typed onto the teleprinter roll.
const tstamp=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;
const txLine=(M,l)=>l.w?`<div class="cl ${l.c||''}"><span class="ctm">${tstamp(l.t)}</span><b>${spk(M,l.w)}</b><span>${l.x}</span></div>`:`<div class="cl note ${l.c||''}"><span class="ctm">${tstamp(l.t)}</span><i>[${l.x}]</i></div>`;
function commsDraw(m){const box=$('#ctx');if(!box||!m.tx)return;if(m.tx.length>m.shownTx){box.insertAdjacentHTML('beforeend',m.tx.slice(m.shownTx).map(l=>txLine(m,l)).join(''));m.shownTx=m.tx.length;box.scrollTop=box.scrollHeight}}
function showTranscript(){const L=S.p2&&S.p2.lastTx;if(!L)return;const M={call:L.call};$('#sum').innerHTML=`<div class="sumbox"><h1>AIR-TO-GROUND TRANSCRIPT</h1><div class="d">${L.n}${L.call?`, call sign ${L.call}`:''}</div><div class="comms"><div class="ctx">${L.tx.map(l=>txLine(M,l)).join('')}</div></div><button data-a="closesum">CLOSE</button></div>`;$('#sum').hidden=false}
// One-off overlays: the memorial after a crew is lost, then the Section 1 summary.
function overlays(){const P=S.p2;if(!P||PL)return;const o=$('#sum');if(P.memo&&o.hidden){o.innerHTML=memorialHTML(P.memo);o.hidden=false;return}if(P.secDone&&!P.secShown&&o.hidden){P.secShown=1;o.innerHTML=sectionHTML();o.hidden=false}}
